describe("targeted rumors (§11)", () => {
  it("answer rumor, sighting, capped, none and duplicate, matching the availability shown beforehand", () => {
    const run = new Run(quick, 4);
    const world: World = { players: { A: S[4], B: S[8], C: S[0] }, rubbings: [source("sun-1", 2), source("sun-2", 0), carried("moon-1", "B")] };
    run.step(START, world);
    run.step(START + 100, world);
    const t = START + 110;
    const asks: [TargetedRumorRequest, string][] = [
      [request("a-sun", "A", "sun"), "rumor"],
      [request("b-sun", "B", "sun"), "rumor"],
    ];
    for (const [ask, expected] of asks) expect(run.available(t, world, ask.playerId, ask.type)).toBe(expected);
    expect(run.available(t, world, "A", "moon")).toBe("sighting");
    expect(run.available(t, world, "B", "moon")).toBe("none");
    const first = run.step(t, world, [request("c1", "A", "moon"), request("c0", "C", "sun")]);
    expect(first.outcomes).toEqual([
      { requestId: "c1", result: "sighting" },
      { requestId: "c0", result: "rumor" },
    ]);
    expect(run.available(t + 1, world, "A", "moon")).toBe("capped");
    const after = run.state;
    const second = run.step(t + 1, world, [
      request("c2", "A", "moon"),
      request("c3", "B", "moon"),
      request("c4", "Z", "sun"),
      request("c1", "A", "moon"),
    ]);
    expect(second.outcomes).toEqual([
      { requestId: "c2", result: "capped" },
      { requestId: "c3", result: "none" },
      { requestId: "c4", result: "none" },
      { requestId: "c1", result: "duplicate" },
    ]);
    expect(second.messages).toEqual([]);
    // A repeated id changes nothing and draws nothing: the very same state as a tick without it.
    const withDuplicate = stepIntel(quick, run.state, viewOf(t + 2, world), [request("c2", "A", "moon")]);
    const without = stepIntel(quick, run.state, viewOf(t + 2, world), []);
    expect(withDuplicate.outcomes).toEqual([{ requestId: "c2", result: "duplicate" }]);
    expect(withDuplicate.state).toEqual(without.state);
    expect(hashState(withDuplicate.state)).toBe(hashState(without.state));
    expect(withDuplicate.messages).toEqual(without.messages);
    expect(after.requestIds).toEqual(["c0", "c1"]);
    // A rumor is not sold twice: with both sun islands already in C's journal, nothing new is left.
    const again = run.step(t + 3, world, [request("c5", "C", "sun")]);
    expect(again.outcomes).toEqual([{ requestId: "c5", result: "none" }]);
    // A later snapshot lifts the cap.
    expect(run.step(START + 200, world, [request("c6", "A", "moon")]).outcomes).toEqual([{ requestId: "c6", result: "sighting" }]);
  });

  it("lift the sighting cap from the carrier reveal on", () => {
    const run = new Run(quick);
    // A holds a full set; B and C carry the other moon and sun. D, then E, steal from A.
    const players = { A: S[4], B: S[8], C: S[0], D: S[2], E: S[6] };
    const world = (moonWith: string, sunWith: string): World => ({
      players,
      rubbings: [carried("sun-1", sunWith), carried("moon-1", moonWith), carried("moon-2", "B"), carried("sun-2", "C")],
    });
    run.step(START, world("A", "A"));
    run.step(quick.carrierRevealTick, world("A", "A"));
    // Two free sightings in one snapshot after the reveal: the second is not capped.
    const first = run.step(quick.carrierRevealTick + 1, world("D", "A"));
    expect(only(to(first, "A"), "carrier-sighting").sightings).toEqual([{ type: "moon", reason: "fresh", sector: 8, name: "South-East Reach" }]);
    const second = run.step(quick.carrierRevealTick + 2, world("D", "E"));
    expect(only(to(second, "A"), "carrier-sighting").sightings).toEqual([{ type: "sun", reason: "fresh", sector: 0, name: "North-West Reach" }]);
    // After the reveal, purchases of carrier-only types are free coverage (the broadcast): covered, never charged.
    const stepped = run.step(quick.carrierRevealTick + 3, world("D", "E"), [request("y", "A", "moon"), request("x", "A", "moon")]);
    expect(stepped.outcomes).toEqual([
      { requestId: "y", result: "covered" },
      { requestId: "x", result: "covered" },
    ]);
    expect(to(stepped, "A")).toEqual([]);
    expect(run.step(quick.carrierRevealTick + 4, world("D", "E"), [request("z", "A", "moon")]).outcomes).toEqual([{ requestId: "z", result: "covered" }]);
  });
});

describe("free coverage (§11): a purchase is never charged for what the broadcast or the pending set gives", () => {
  /** Buys after checking that `targetedRumorAvailability` and `freeCoverage` agree with the outcome. */
  function buy(run: Run, tick: number, world: World, requestId: string, playerId: string, type: RubbingType): IntelStepResult {
    const shown = run.available(tick, world, playerId, type);
    expect(freeCoverage(run.config, run.state, viewOf(tick, world), playerId, type)).toBe(shown === "covered" ? "covered" : null);
    const stepped = run.step(tick, world, [request(requestId, playerId, type)]);
    expect(stepped.outcomes).toEqual([{ requestId, result: shown }]);
    return stepped;
  }
  // A holds sun and lacks moon; B carries the only moon, then C drops a moon into a cache in Northern Waters.
  const players = { A: S[4], B: S[8], C: S[0] };
  const carrierOnly: World = { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "B"), carried("moon-2", "C")] };
  const withCache: World = { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "B"), cached("moon-2", S[1])] };
  const reveal = quick.carrierRevealTick;

  it("cover a carrier-only purchase from the minute-28 reveal on, in the first and in a later interval", () => {
    const run = new Run(quick);
    run.step(START, carrierOnly);
    run.step(reveal - 100, carrierOnly);
    // Before the reveal the same purchase is a charged sighting.
    expect(buy(run, reveal - 50, carrierOnly, "before", "A", "moon").outcomes).toEqual([{ requestId: "before", result: "sighting" }]);
    // On the reveal tick itself (the first interval, with the first broadcast) and later: covered, and nothing is sent.
    const first = buy(run, reveal, carrierOnly, "first", "A", "moon");
    expect(first.outcomes).toEqual([{ requestId: "first", result: "covered" }]);
    expect(to(first, "A")).toEqual([]);
    expect(everyone(first).map((body) => body.kind)).toEqual(["carrier-report"]);
    expect(buy(run, reveal + 50, carrierOnly, "first-again", "A", "moon").outcomes).toEqual([{ requestId: "first-again", result: "covered" }]);
    const later = buy(run, reveal + 250, carrierOnly, "later", "A", "moon");
    expect(later.outcomes).toEqual([{ requestId: "later", result: "covered" }]);
    expect(to(later, "A")).toEqual([]);
  });

  it("still charge a purchase with a cache target after the reveal as a rumor", () => {
    const run = new Run(quick);
    run.step(START, carrierOnly);
    run.step(reveal, carrierOnly);
    const bought = buy(run, reveal + 10, withCache, "cache", "A", "moon");
    expect(bought.outcomes).toEqual([{ requestId: "cache", result: "rumor" }]);
    expect(only(to(bought, "A"), "rumor")).toMatchObject({ type: "moon", reason: "targeted", target: { kind: "sector", sector: 1 } });
    // Free coverage is only for a carrier-only type: a held type still has nothing to sell.
    expect(buy(run, reveal + 20, withCache, "held", "A", "sun").outcomes).toEqual([{ requestId: "held", result: "none" }]);
  });

  /** A's sighting for the snapshot of START + 100 is spent on a stolen sun, so the moon stolen next waits. */
  function pendingMoon(seed: number): { run: Run; world: World } {
    const run = new Run(quick, seed);
    // A holds a full set; B carries the other moon, D the other sun; C steals A's sun, then A's moon.
    const world = (stage: number): World => ({
      players: { A: S[4], B: S[8], C: S[0], D: S[2] },
      rubbings: [carried("sun-1", stage >= 1 ? "C" : "A"), carried("moon-1", stage >= 2 ? "C" : "A"), carried("moon-2", "B"), carried("sun-2", "D")],
    });
    run.step(START, world(0));
    run.step(START + 100, world(0));
    expect(only(to(run.step(START + 110, world(1)), "A"), "carrier-sighting").sightings).toMatchObject([{ type: "sun", reason: "fresh" }]);
    expect(to(run.step(START + 120, world(2)), "A")).toEqual([]);
    expect(run.state.players.find((player) => player.id === "A")!.pending).toEqual({ types: [{ type: "moon", reason: "fresh", tick: START + 120 }] });
    return { run, world: world(2) };
  }

  it("cover a purchase of a pending carrier-only type, which the next boundary gives free", () => {
    const { run, world } = pendingMoon(1);
    const covered = buy(run, START + 130, world, "pending", "A", "moon");
    expect(covered.outcomes).toEqual([{ requestId: "pending", result: "covered" }]);
    expect(to(covered, "A")).toEqual([]);
    const boundary = run.step(START + 200, world);
    expect(only(to(boundary, "A"), "carrier-sighting").sightings).toEqual([{ type: "moon", reason: "fresh", sector: 8, name: "South-East Reach" }]);
  });

  it("charge a rumor for a pending type whose cache appears mid-interval, and drop the pending entry at the boundary without a no-lead", () => {
    const { run } = pendingMoon(2);
    // D leaves before the boundary, B drops the other moon into a cache in Eastern Waters and picks up D's sun.
    const at = { A: S[4], B: S[8], C: S[0] };
    const cacheWorld: World = { players: at, rubbings: [carried("sun-1", "C"), carried("moon-1", "C"), cached("moon-2", S[5]), carried("sun-2", "B")] };
    const bought = buy(run, START + 150, cacheWorld, "cache", "A", "moon");
    expect(bought.outcomes).toEqual([{ requestId: "cache", result: "rumor" }]);
    expect(to(bought, "A")).toEqual([{ kind: "rumor", tick: START + 150, entry: 1, type: "moon", reason: "targeted", target: { kind: "sector", sector: 5, name: "Eastern Waters" } }]);
    expect(run.state.players.find((player) => player.id === "A")!.pending).toEqual({ types: [{ type: "moon", reason: "fresh", tick: START + 120 }] });
    const boundary = run.step(START + 200, cacheWorld);
    expect(to(boundary, "A")).toEqual([]);
    expect(run.state.players.find((player) => player.id === "A")!.pending).toBeNull();
    // Nothing is left to buy: the cache is in the journal.
    expect(buy(run, START + 210, cacheWorld, "after", "A", "moon").outcomes).toEqual([{ requestId: "after", result: "none" }]);
  });
});

/** Every ordering of `items`. */
function permutations<T>(items: readonly T[]): T[][] {
  if (items.length <= 1) return [[...items]];
  return items.flatMap((item, index) => permutations([...items.slice(0, index), ...items.slice(index + 1)]).map((rest) => [item, ...rest]));
}

