    return run.state;
  }
  const fresh = (playerId: string, type: RubbingType): LeadTrigger => ({ playerId, type, free: { type, reason: "fresh", tick: T0 } });
  const replacement = (playerId: string, type: RubbingType): LeadTrigger => ({ playerId, type, free: { type, reason: "replacement", tick: T0 } });
  const paid = (requestId: string, playerId: string, type: RubbingType): LeadTrigger => ({ playerId, type, requestId });
  /** The three phases on one ordering of the triggers, deciding the start rumors of `starting` too. */
  function phases(state: IntelState, triggers: readonly LeadTrigger[], starting: readonly string[] = []) {
    const decided = decideLeads(quickAlpha, state, view, gatherLeads(triggers), starting);
    return { decided, answers: Object.fromEntries([...answerRequests(decided.deliveries)].sort(([a], [b]) => (a < b ? -1 : 1))) };
  }
  function sameForEveryOrder(state: IntelState, triggers: readonly LeadTrigger[], starting: readonly string[] = []) {
    const first = phases(state, triggers, starting);
    for (const order of permutations(triggers)) expect(phases(state, order, starting)).toEqual(first);
    return first;
  }

  it("decide three triggers across three types identically in all six orders, in one message in type order", () => {
    const sectors = new Map<RubbingType, Set<number>>();
    for (let seed = 0; seed < 16; seed++) {
      const { decided, answers } = sameForEveryOrder(ready(seed), [paid("t1", "A", "tide"), replacement("A", "moon"), fresh("A", "sun")]);
      expect(decided.leads).toEqual([]);
      expect(decided.sightings).toHaveLength(1);
      const [message] = decided.sightings;
      expect(message).toMatchObject({ playerId: "A", seenTick: START });
      expect(message!.sightings.map(({ type, reason }) => [type, reason])).toEqual([
        ["sun", "fresh"],
        ["moon", "replacement"],
        ["tide", "targeted"],
      ]);
      for (const sighting of message!.sightings) {
        expect(contested[sighting.type]).toContain(sighting.sector);
        if (!sectors.has(sighting.type)) sectors.set(sighting.type, new Set());
        sectors.get(sighting.type)!.add(sighting.sector);
      }
      expect(answers).toEqual({ t1: "sighting" });
      expect(decided.pending.get("A")).toBeNull();
    }
    // The contest is real: over the seeds each type's sector is drawn from both of its carriers' sectors.
    for (const type of ["sun", "moon", "tide"] as const) expect([...sectors.get(type)!].sort((a, b) => a - b)).toEqual(contested[type]);
  });

  it("cover a paid request by a free trigger or a lower request id, and deliver two players' purchases of one type", () => {
    const triggers = [paid("a2", "A", "sun"), fresh("A", "sun"), paid("a3", "A", "moon"), paid("a1", "A", "moon"), paid("f1", "F", "moon")];
    const { decided, answers } = sameForEveryOrder(ready(3), triggers);
    // A's sun is free (the loss), so the paid sun is covered; of A's two moons the first by id is charged.
    expect(answers).toEqual({ a1: "sighting", a2: "covered", a3: "covered", f1: "sighting" });
    expect(decided.sightings.map(({ playerId, sightings }) => [playerId, sightings.map(({ type, reason }) => `${type}:${reason}`)])).toEqual([
      ["A", ["sun:fresh", "moon:targeted"]],
      ["F", ["moon:targeted"]],
    ]);
    // F's purchase is decided the same with or without A's triggers.
    const alone = phases(ready(3), [paid("f1", "F", "moon")]);
    expect(alone.answers).toEqual({ f1: "sighting" });
    expect(alone.decided.sightings).toEqual(decided.sightings.filter((message) => message.playerId === "F"));
  });

  it("give every request of a capped (player, type) the same capped answer, and keep only the free type pending", () => {
    const state = ready(4);
    const spent: IntelState = { ...state, players: state.players.map((player) => (player.id === "A" ? { ...player, lastSightingBoundary: 1 } : player)) };
    const { decided, answers } = sameForEveryOrder(spent, [fresh("A", "sun"), paid("s1", "A", "sun"), paid("t2", "A", "tide"), paid("t1", "A", "tide"), paid("f1", "F", "tide")]);
    expect(answers).toEqual({ s1: "capped", t1: "capped", t2: "capped", f1: "sighting" });
    expect(decided.sightings.map((message) => message.playerId)).toEqual(["F"]);
    expect(decided.pending.get("A")).toEqual({ types: [{ type: "sun", reason: "fresh", tick: T0 }] });
  });

  it("cover paid requests by a free rumor of the same type, and charge only the first request of a paid rumor", () => {
    const state = ready(5);
    // A's start rumor named one storm island; B's too. A's replacement and B's purchases each get the other island.
    const triggers = [paid("s2", "A", "storm"), replacement("A", "storm"), paid("s1", "A", "storm"), paid("b2", "B", "storm"), paid("b1", "B", "storm")];
    const { decided, answers } = sameForEveryOrder(state, triggers);
    expect(answers).toEqual({ s1: "covered", s2: "covered", b1: "rumor", b2: "covered" });
    expect(decided.leads.map((lead) => [lead.playerId, lead.kind, lead.type, lead.reason])).toEqual([
      ["A", "rumor", "storm", "replacement"],
      ["B", "rumor", "storm", "targeted"],
    ]);
    expect(decided.sightings).toEqual([]);
  });

  it("cover paid requests by the start rumor of their type with decideLeads's starting players, and charge them without", () => {
    for (let seed = 0; seed < 8; seed++) {
      const state = ready(seed);
      // A's start rumor at control start named one storm island; a start decided now names the other.
      const triggers = [paid("s2", "A", "storm"), paid("s1", "A", "storm"), fresh("A", "sun")];
      const started = sameForEveryOrder(state, triggers, ["A"]);
      expect(started.answers).toEqual({ s1: "covered", s2: "covered" });
      expect(started.decided.leads.map((lead) => [lead.playerId, lead.kind, lead.type, lead.reason])).toEqual([["A", "rumor", "storm", "start"]]);
      expect(started.decided.deliveries.find((entry) => entry.type === "storm")!.delivery).toBe("free");
      // The same triggers without the start: the first storm request by id buys that island.
      const plain = sameForEveryOrder(state, triggers);
      expect(plain.answers).toEqual({ s1: "rumor", s2: "covered" });
      expect(plain.decided.leads.map((lead) => [lead.playerId, lead.kind, lead.type, lead.reason])).toEqual([["A", "rumor", "storm", "targeted"]]);
      expect(started.decided.sightings).toEqual(plain.decided.sightings);
    }
  });

  it("keep one free trigger of two for one (player, type) in every order: the earliest tick, then fresh before replacement", () => {
    const earlier = (reason: "fresh" | "replacement"): LeadTrigger => ({ playerId: "A", type: "moon", free: { type: "moon", reason, tick: T0 - 50 } });
    const cases: [LeadTrigger[], LeadTrigger][] = [
      // A pending loss from an earlier tick and this step's replacement: the earlier loss.
      [[earlier("fresh"), replacement("A", "moon")], earlier("fresh")],
      // A pending replacement from an earlier tick and this step's loss: the earlier tick beats fresh.
      [[earlier("replacement"), fresh("A", "moon")], earlier("replacement")],
      // Both on this tick: fresh before replacement.
      [[replacement("A", "moon"), fresh("A", "moon")], fresh("A", "moon")],
    ];
    for (const [free, kept] of cases) {
      const triggers = [...free, paid("m1", "A", "moon")];
      const keptFree = (kept as Extract<LeadTrigger, { free: unknown }>).free;
      for (const order of permutations(triggers)) {
        expect(gatherLeads(order)).toEqual([{ playerId: "A", type: "moon", free: keptFree, requestIds: ["m1"] }]);
      }
      const { decided, answers } = sameForEveryOrder(ready(6), triggers);
      expect(answers).toEqual({ m1: "covered" });
      expect(decided.sightings).toHaveLength(1);
      expect(decided.sightings[0]!.sightings.map(({ type, reason }) => [type, reason])).toEqual([["moon", keptFree.reason]]);
    }
  });

  it("answer every request of an undeliverable (player, type) none, charging none, in every order", () => {
    // B holds sun: nothing to sell, however many requests. A's purchase of sun is delivered all the same.
    const { decided, answers } = sameForEveryOrder(ready(7), [paid("b2", "B", "sun"), paid("b1", "B", "sun"), paid("b3", "B", "sun"), paid("a1", "A", "sun")]);
    expect(answers).toEqual({ a1: "sighting", b1: "none", b2: "none", b3: "none" });
    expect(decided.deliveries.map(({ playerId, type, delivery }) => [playerId, type, delivery])).toEqual([
      ["A", "sun", "sighting"],
      ["B", "sun", "none"],
    ]);
    expect(decided.sightings.map((message) => message.playerId)).toEqual(["A"]);
    expect(decided.leads).toEqual([]);
  });

  it("answer a phase-3 group from its delivery alone", () => {
    const answers = answerRequests([
      { requestIds: ["c", "a", "b"], delivery: "sighting" },
      { requestIds: ["e", "d"], delivery: "free" },
      { requestIds: ["g", "f"], delivery: "capped" },
      { requestIds: ["h"], delivery: "none" },
      { requestIds: ["j", "i"], delivery: "rumor" },
    ]);
    expect(Object.fromEntries(answers)).toEqual({ a: "sighting", b: "covered", c: "covered", d: "covered", e: "covered", f: "capped", g: "capped", h: "none", i: "rumor", j: "covered" });
  });

  it("never let a start ask for a sighting, by type", () => {
    const reasons: CarrierSightingReason[] = ["fresh", "targeted", "replacement"];
    // @ts-expect-error: a start is not a sighting reason.
    const start: CarrierSightingReason = "start";
    expect(reasons).not.toContain(start);
    // The field itself: a sighting's reason, and the reason of a sighting inside a message body, can't be a start.
    // @ts-expect-error: a start is not a CarrierSighting's reason.
    const sighting: CarrierSighting = { type: "sun", reason: "start", sector: 0, name: "North-West Reach" };
    // @ts-expect-error: nor the reason of a carrier-sighting body's sighting.
    const body: IntelMessageBody = { kind: "carrier-sighting", tick: 1, seenTick: 0, sightings: [{ type: "sun", reason: "start", sector: 0, name: "North-West Reach" }] };
    expect([sighting.reason, body.kind]).toEqual(["start", "carrier-sighting"]);
  });
});

describe("triggers out of type order in one step, with contested sectors", () => {
  // As above, and A carries a tide of their own, which F steals at START + 110.
  const players = { A: S[4], B: S[0], C: S[2], D: S[6], E: S[8], F: S[5] };
  const rubbings = (stolen: boolean): IntelRubbing[] => [
    carried("sun-1", "B"),
    carried("sun-2", "C"),
    carried("moon-1", "D"),
    carried("moon-2", "E"),
    carried("tide-1", "B"),
    carried("tide-2", "E"),
    carried("tide-3", stolen ? "F" : "A"),
    carried("storm-1", "C"),
    source("storm-2", 3),
    source("storm-3", 1),
  ];
  const requests = [
    request("z-moon", "A", "moon"),
    request("t-tide", "A", "tide"),
    request("m-sun", "A", "sun"),
    request("a-sun", "A", "sun"),
    request("f-sun", "F", "sun"),
    request("b-storm", "A", "storm"),
  ];
  function stepTwice(seed: number, reversed: boolean): IntelStepResult {
    const run = new Run(quickAlpha, seed);
    run.step(START, { players, rubbings: rubbings(false) });
    run.step(START + 100, { players, rubbings: rubbings(false) });
    const flip = <T>(items: readonly T[]) => (reversed ? [...items].reverse() : [...items]);
    const view: IntelWorldView = { tick: START + 110, players: flip(viewOf(0, { players, rubbings: [] }).players), rubbings: flip(rubbings(true)) };
    return stepIntel(quickAlpha, run.state, view, flip(requests));
  }
  const byId = (result: IntelStepResult) => [...result.outcomes].sort((a, b) => (a.requestId < b.requestId ? -1 : 1));

  it("send one message in type order, charge one request per (player, type), and match the reversed step exactly", () => {
    for (let seed = 0; seed < 8; seed++) {
      const forward = stepTwice(seed, false);
      const reversed = stepTwice(seed, true);
      expect(reversed.messages).toEqual(forward.messages);
      expect(byId(reversed)).toEqual(byId(forward));
      expect(hashState(reversed.state)).toBe(hashState(forward.state));
      expect(byId(forward)).toEqual([
        { requestId: "a-sun", result: "sighting" },
        // A's storm: the other island than the start rumor's, bought as a rumor.
        { requestId: "b-storm", result: "rumor" },
        { requestId: "f-sun", result: "sighting" },
        { requestId: "m-sun", result: "covered" },
        // A's lost tide is a free sighting, so the paid tide is covered.
        { requestId: "t-tide", result: "covered" },
        { requestId: "z-moon", result: "sighting" },
      ]);
      const sighting = only(to(forward, "A"), "carrier-sighting");
      expect(sighting.seenTick).toBe(START);
      expect(sighting.sightings.map(({ type, reason }) => `${type}:${reason}`)).toEqual(["sun:targeted", "moon:targeted", "tide:fresh"]);
      const allowed: Record<string, number[]> = { sun: [0, 2], moon: [6, 8], tide: [0, 8] };
      for (const { type, sector } of sighting.sightings) expect(allowed[type]).toContain(sector);
      expect(only(to(forward, "A"), "rumor")).toMatchObject({ type: "storm", reason: "targeted" });
      expect(only(to(forward, "F"), "carrier-sighting").sightings.map(({ type }) => type)).toEqual(["sun"]);
    }
  });
});

describe("reveals (§2, §5)", () => {
  it("announce the first full set's sector to everyone and route each full-set holder, suspending a broken set", () => {
    const run = new Run(quick);
    const players = { A: S[0], B: S[8], C: S[2] };
    run.step(START, { players, rubbings: [carried("sun-1", "A"), source("moon-1", 1), carried("moon-2", "B"), carried("sun-2", "C")] });
    const complete = run.step(START + 300, { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "A"), carried("moon-2", "B"), carried("sun-2", "C")] });
    expect(everyone(complete)).toEqual([{ kind: "final-sector", tick: START + 300, sector: 4, name: "Central Waters" }]);
    expect(only(to(complete, "A"), "final-route")).toEqual({ kind: "final-route", tick: START + 300, x: FINAL.x, y: FINAL.y, restored: false });
    // B steals A's moon: A's route goes inactive; B lacks sun, so nothing for B yet.
    const lost = run.step(START + 400, { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "B"), carried("moon-2", "C"), carried("sun-2", "B")] });
    expect(to(lost, "A").filter((body) => body.kind.startsWith("final"))).toEqual([{ kind: "final-route-inactive", tick: START + 400 }]);
    // B completes (moon-1 and sun-2) on the same tick: a route of their own, and no second announcement.
    expect(only(to(lost, "B"), "final-route")).toMatchObject({ restored: false });
    expect(everyone(lost)).toEqual([]);
    // A wins a moon back: the route is restored.
    const back = run.step(START + 500, { players, rubbings: [carried("sun-1", "A"), carried("moon-2", "A"), carried("moon-1", "B"), carried("sun-2", "B")] });
    expect(only(to(back, "A"), "final-route")).toEqual({ kind: "final-route", tick: START + 500, x: FINAL.x, y: FINAL.y, restored: true });
    expect(to(back, "B").filter((body) => body.kind.startsWith("final"))).toEqual([]);
    expect(everyone(back)).toEqual([]);
    // Only a full-set holder ever receives the exact point.
    const all = [complete, lost, back].flatMap((stepped) => stepped.messages);
    expect(all.filter((message) => "x" in message.body).every((message) => message.to.kind === "player")).toBe(true);
  });

  const revealWorld: World = {
    players: { A: S[4], B: S[5] },
    rubbings: [source("sun-1", 0), source("sun-2", 0), source("moon-1", 3), cached("moon-2", S[1]), carried("sun-3", "B"), reserved("moon-3", "A")],
  };

  it("reveal source and cache sectors exactly at minute 20, once, also across skipped ticks", () => {
    const run = new Run(real);
    run.step(START, revealWorld);
    const minute20 = START + 20 * 60 * 20;
    expect(real.sectorRevealTick).toBe(minute20);
    expect(everyone(run.step(minute20 - 1, revealWorld))).toEqual([]);
    expect(everyone(run.step(minute20, revealWorld))).toEqual([
      {
        kind: "sector-reveal",
        tick: minute20,
        sources: [
          { sector: 0, name: "North-West Reach" },
          { sector: 8, name: "South-East Reach" },
        ],
        caches: [{ sector: 1, name: "Northern Waters" }],
      },
    ]);
    expect(everyone(run.step(minute20 + 1, revealWorld))).toEqual([]);
    const skipping = new Run(real);
    skipping.step(START, revealWorld);
    skipping.step(minute20 - 10, revealWorld);
    expect(everyone(skipping.step(minute20 + 10, revealWorld)).map((body) => body.kind)).toEqual(["sector-reveal"]);
  });

  it("publish carrier sectors at minute 28 and every 30 s after, once per crossed boundary run", () => {
    const run = new Run(real);
    run.step(START, revealWorld);
    const minute28 = START + 28 * 60 * 20;
    expect(real.carrierRevealTick).toBe(minute28);
    const moved: World = { ...revealWorld, players: { A: S[6], B: S[7] } };
    run.step(minute28 - 600, revealWorld);
    expect(everyone(run.step(minute28 - 1, moved))).toEqual([]);
    const report = [
      { sector: 6, name: "South-West Reach", type: "moon" },
      { sector: 7, name: "Southern Waters", type: "sun" },
    ];
    // The latest snapshot is taken on the same beat, so the first report is of minute 28 itself.
    expect(everyone(run.step(minute28, moved))).toEqual([{ kind: "carrier-report", tick: minute28, seenTick: minute28, carriers: report }]);
    expect(everyone(run.step(minute28 + 599, revealWorld))).toEqual([]);
    expect(everyone(run.step(minute28 + 600, revealWorld))).toEqual([
      {
        kind: "carrier-report",
        tick: minute28 + 600,
        seenTick: minute28 + 600,
        carriers: [
          { sector: 4, name: "Central Waters", type: "moon" },
          { sector: 5, name: "Eastern Waters", type: "sun" },
        ],
      },
    ]);
    // Skipping over two beats sends one report.
    run.step(minute28 + 601, revealWorld);
    const skipped = run.step(minute28 + 1_250, moved);
    expect(everyone(skipped)).toEqual([{ kind: "carrier-report", tick: minute28 + 1_250, seenTick: minute28 + 1_250, carriers: report }]);
    expect(run.state.lastCarrierBroadcast).toBe(2);
    // Minute 35 is the claim code's business: nothing new here.
    expect(everyone(run.step(START + 35 * 60 * 20, revealWorld)).map((body) => body.kind)).toEqual(["carrier-report"]);
  });

  it("replay a script to the same state hash and messages", () => {
    const script = [START, START + 100, START + 250, START + 2_000].map((tick) => ({ view: viewOf(tick, revealWorld) }));
    const first = replayIntel(quick, createIntelState(quick, 11), script);
    const second = replayIntel(quick, createIntelState(quick, 11), script);
    expect(second.hash).toBe(first.hash);
    expect(second.messages).toEqual(first.messages);
    const kinds = new Set(first.messages.map((message: IntelMessage) => message.body.kind));
    expect(kinds.has("sector-reveal") && kinds.has("carrier-report")).toBe(true);
  });
});

describe("the world view", () => {
  it("refuse a tick that does not advance, duplicates, an unknown carrier or island and a doubled type", () => {
    const state = stepIntel(quick, createIntelState(quick, 1), viewOf(START, { players: { A: S[0] }, rubbings: [] })).state;
    const bad = (world: World, tick = START + 1) => () => stepIntel(quick, state, viewOf(tick, world));
    expect(bad({ players: { A: S[0] }, rubbings: [] }, START)).toThrow(/expected a tick after/);
    expect(bad({ players: { A: S[0] }, rubbings: [carried("sun-1", "Z")] })).toThrow(/not in the view/);
    expect(bad({ players: { A: S[0] }, rubbings: [carried("sun-1", "A"), carried("sun-1", "A")] })).toThrow(/appears twice/);
    expect(bad({ players: { A: S[0] }, rubbings: [carried("sun-1", "A"), reserved("sun-2", "A")] })).toThrow(/two sun/);
    expect(bad({ players: { A: S[0] }, rubbings: [{ id: "tide-1", type: "tide", place: { kind: "cache", ...S[0] } }] })).toThrow(/outside the preset/);
    expect(bad({ players: { A: S[0] }, rubbings: [{ id: "sun-1", type: "sun", place: { kind: "source", island: 4, ...S[0] } }] })).toThrow(/unknown island/);
    expect(() => stepIntel(quick, state, { tick: START + 1, players: [{ id: "A", ...S[0] }, { id: "A", ...S[1] }], rubbings: [] })).toThrow(/appears twice/);
    expect(() => createIntelState(quick, 1, START)).toThrow(RangeError);
  });
});

