250	interface Facts {
251	  readonly players: ReadonlySet<string>;
252	  readonly held: ReadonlyMap<string, readonly RubbingType[]>;
253	  readonly sourceIslands: readonly { type: RubbingType; island: number }[];
254	  readonly cacheSectors: readonly { type: RubbingType; sector: number }[];
255	  readonly carriers: readonly { type: RubbingType; sector: number; holder: string }[];
256	}
257	
258	function factsOf(config: IntelConfig, view: IntelWorldView): Facts {
259	  const positions = new Map(view.players.map((player) => [player.id, player]));
260	  const held = new Map<string, RubbingType[]>(view.players.map((player) => [player.id, []]));
261	  const sourceIslands: { type: RubbingType; island: number }[] = [];
262	  const cacheSectors: { type: RubbingType; sector: number }[] = [];
263	  const carriers: { type: RubbingType; sector: number; holder: string }[] = [];
264	  for (const rubbing of view.rubbings) {
265	    const place = rubbing.place;
266	    if (place.kind === "source") sourceIslands.push({ type: rubbing.type, island: place.island });
267	    else if (place.kind === "cache") cacheSectors.push({ type: rubbing.type, sector: sectorOf(config, place) });
268	    else {
269	      held.get(place.playerId)!.push(rubbing.type);
270	      carriers.push({ type: rubbing.type, sector: sectorOf(config, positions.get(place.playerId)!), holder: place.playerId });
271	    }
272	  }
273	  return { players: new Set(positions.keys()), held, sourceIslands, cacheSectors, carriers };
274	}
275	
276	/** The keys each message kind may carry: none is an id, and only `final-route` has a position. */
277	const BODY_KEYS: Record<IntelMessageKind, readonly string[]> = {
278	  rumor: ["entry", "kind", "reason", "target", "tick", "type"],
279	  "carrier-sighting": ["kind", "seenTick", "sightings", "tick"],
280	  "no-lead": ["kind", "reason", "tick", "type"],
281	  "rumor-stale": ["entry", "kind", "tick", "type"],
282	  "rumor-resolved": ["entry", "kind", "tick", "type"],
283	  "final-sector": ["kind", "name", "sector", "tick"],
284	  "final-route": ["kind", "restored", "tick", "x", "y"],
285	  "final-route-inactive": ["kind", "tick"],
286	  "sector-reveal": ["caches", "kind", "sources", "tick"],
287	  "carrier-report": ["carriers", "kind", "seenTick", "tick"],
288	};
289	const BROADCASTS: ReadonlySet<IntelMessageKind> = new Set(["final-sector", "sector-reveal", "carrier-report"]);
290	const NESTED_KEYS = new Set(["kind", "island", "sector", "name", "type", "reason"]);
291	/** A start never asks for a sighting. */
292	const SIGHTING_REASONS: ReadonlySet<string> = new Set(["fresh", "targeted", "replacement"]);
293	
294	/** Every kind, outcome and path the property runs must reach, filled as they run. */
295	const EXERCISED = new Set<string>();
296	const MUST_EXERCISE = [
297	  ...Object.keys(BODY_KEYS).map((kind) => `message:${kind}`),
298	  ...(["rumor", "sighting", "covered", "capped", "none", "duplicate"] satisfies TargetedRumorResult[]).map((result) => `outcome:${result}`),
299	  ...["start", "fresh", "targeted", "replacement"].map((reason) => `rumor:${reason}`),
300	  ...["fresh", "targeted", "replacement"].map((reason) => `sighting:${reason}`),
301	  "rumor:island",
302	  "rumor:sector",
303	  "route:restored",
304	  "sighting:deferred",
305	  "sighting:deferred-delivered",
306	  "sighting:several-types",
307	  "sighting:free-deferred",
308	  "sighting:free-same-step",
309	  "covered:broadcast",
310	  "covered:pending",
311	  "skipped-ticks",
312	];
313	
314	function allStrings(value: unknown, out: string[] = []): string[] {
315	  if (typeof value === "string") out.push(value);
316	  else if (Array.isArray(value)) for (const item of value) allStrings(item, out);
317	  else if (typeof value === "object" && value !== null) for (const item of Object.values(value)) allStrings(item, out);
318	  return out;
319	}
320	
321	/**
322	 * Checks every message of a run against the design's rules (§3, §5, §11, §16), with the views that produced them. It
323	 * returns nothing and throws on the first violation, with the tick and message.
324	 */
325	class Checker {
326	  private readonly rumors = new Map<string, { type: RubbingType; closed: boolean; target: unknown }>();
327	  private readonly sightings = new Map<string, number>();
328	  private readonly carriersAt = new Map<number, Facts["carriers"]>();
329	  private readonly ids = new Set<string>();
330	  private previousTick = -Infinity;
331	  private previousState: IntelState | undefined;
332	
333	  constructor(
334	    private readonly config: IntelConfig,
335	    private readonly skipping: boolean,
336	  ) {}
337	
338	  check(
339	    view: IntelWorldView,
340	    messages: readonly IntelMessage[],
341	    state: IntelState,
342	    requests: readonly TargetedRumorRequest[] = [],
343	    outcomes: readonly TargetedRumorOutcome[] = [],
344	  ): void {
345	    const config = this.config;
346	    const tick = view.tick;
347	    if (tick - this.previousTick > 1 && this.previousTick >= config.controlStartTick) EXERCISED.add("skipped-ticks");
348	    this.previousTick = tick;
349	    const facts = factsOf(config, view);
350	    this.carriersAt.set(tick, facts.carriers);
351	    for (const player of view.players) this.ids.add(player.id);
352	    for (const rubbing of view.rubbings) this.ids.add(rubbing.id);
353	    if (state.players.some((player) => player.pending !== null)) EXERCISED.add("sighting:deferred");
354	    const fail = (message: IntelMessage, why: string): never => {
355	      throw new Error(`tick ${tick}: ${why}: ${JSON.stringify(message)}`);
356	    };
357	    if (tick < config.controlStartTick && messages.length > 0) fail(messages[0]!, "a message before control start");
358	    // Who had already spent this snapshot's sighting before this step.
359	    const snapshotIndex = Math.floor((tick - config.controlStartTick) / config.carrierIntervalTicks);
360	    const cappedBefore = new Set(
361	      tick >= config.controlStartTick && tick < config.carrierRevealTick ? [...facts.players].filter((id) => this.sightings.has(`${id}@${snapshotIndex}`)) : [],
362	    );
363	    const sightedThisStep = new Set<string>();
364	    for (const message of messages) {
365	      const body = message.body;
366	      EXERCISED.add(`message:${body.kind}`);
367	      if (body.tick !== tick) fail(message, "wrong tick");
368	      // Keys: exactly the allowed ones, nested ones from the small sector/target vocabulary.
369	      expect(Object.keys(body).sort()).toEqual([...BODY_KEYS[body.kind]]);
370	      for (const nested of ["target", "sources", "caches", "carriers", "sightings"] as const) {
371	        const value = (body as Record<string, unknown>)[nested];
372	        if (value === undefined) continue;
373	        for (const item of Array.isArray(value) ? value : [value]) {
374	          for (const key of Object.keys(item as object)) if (!NESTED_KEYS.has(key)) fail(message, `nested key ${key}`);
375	        }
376	      }
377	      // No id anywhere in a body.
378	      for (const text of allStrings(body)) if (this.ids.has(text)) fail(message, `the id ${text} leaks`);
379	      // Addressing: broadcasts to everyone, everything else to one player present now.
380	      if (BROADCASTS.has(body.kind)) {
381	        if (message.to.kind !== "everyone") fail(message, "a broadcast addressed to someone");
382	        continue;
383	      }
384	      if (message.to.kind !== "player" || !facts.players.has(message.to.playerId)) fail(message, "not addressed to one present player");
385	      const recipient = (message.to as { playerId: string }).playerId;
386	      const held = facts.held.get(recipient)!;
387	      const complete = config.types.every((type) => held.includes(type));
388	      const key = (entry: number) => `${recipient}#${entry}`;
389	      switch (body.kind) {
390	        case "final-route":
391	          // The only exact position ever sent, and only to a full-set holder.
392	          if (!complete || body.x !== config.finalIsland.x || body.y !== config.finalIsland.y) fail(message, "a route to a player without a full set");
393	          if (body.restored) EXERCISED.add("route:restored");
394	          break;
395	        case "final-route-inactive":
396	          if (complete) fail(message, "a route suspended for a full set");
397	          break;
398	        case "rumor": {
399	          EXERCISED.add(`rumor:${body.reason}`);
400	          EXERCISED.add(`rumor:${body.target.kind}`);
401	          if (held.includes(body.type)) fail(message, "a rumor for a held type");
402	          const target = body.target;
403	          const there =
404	            target.kind === "island"
405	              ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
406	              : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
407	          if (!there) fail(message, "a rumor pointing at nothing");
408	          // Sources before caches: a cache lead only when no sealed source of the type is left outside the journal.
409	          if (target.kind === "sector") {
410	            const journaled = this.activeIslands(recipient, body.type);
411	            if (facts.sourceIslands.some((source) => source.type === body.type && !journaled.has(source.island))) {
412	              fail(message, "a cache rumor while an eligible sealed source existed");
413	            }
414	          }
415	          if (this.rumors.has(key(body.entry))) fail(message, "a journal entry reused");
416	          this.rumors.set(key(body.entry), { type: body.type, closed: false, target });
417	          break;
418	        }
419	        case "rumor-stale":
420	        case "rumor-resolved": {
421	          // Only journal rumors close; a carrier sighting has no entry, so it can never go stale.
422	          const rumor = this.rumors.get(key(body.entry));
423	          if (rumor === undefined || rumor.closed || rumor.type !== body.type) fail(message, "closing no open journal rumor");
424	          rumor!.closed = true;
425	          if (body.kind === "rumor-resolved" && !held.includes(body.type)) fail(message, "resolved without the type");
426	          if (body.kind === "rumor-stale") {
427	            if (held.includes(body.type)) fail(message, "stale although the holder has the type");
428	            const target = rumor!.target as { kind: "island"; island: number } | { kind: "sector"; sector: number };
429	            const there =
430	              target.kind === "island"
431	                ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
432	                : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
433	            if (there) fail(message, "stale while the target still holds the type");
434	          }
435	          break;
436	        }
437	        case "carrier-sighting": {
438	          if (body.sightings.length === 0) fail(message, "a sighting message with no sighting");
439	          if (sightedThisStep.has(recipient)) fail(message, "a second sighting message in one step");
440	          sightedThisStep.add(recipient);
441	          if (new Set(body.sightings.map((sighting) => sighting.type)).size !== body.sightings.length) fail(message, "a type sighted twice in one message");
442	          if (body.sightings.length > 1) EXERCISED.add("sighting:several-types");
443	          if (body.seenTick >= tick) fail(message, "a sighting of the present");
444	          const age = tick - body.seenTick;
445	          const interval = config.carrierIntervalTicks;
446	          if (!this.skipping && (age < interval || age >= 2 * interval)) fail(message, `a sighting ${age} ticks old`);
447	          const then = this.carriersAt.get(body.seenTick);
448	          if (then === undefined) fail(message, "a sighting of a tick never seen");
449	          for (const sighting of body.sightings) {
450	            if (!SIGHTING_REASONS.has(sighting.reason)) fail(message, `a sighting for the reason ${sighting.reason}`);
451	            EXERCISED.add(`sighting:${sighting.reason}`);
452	            if (held.includes(sighting.type)) fail(message, "a sighting for a held type");
453	            if (!then!.some((carrier) => carrier.type === sighting.type && carrier.sector === sighting.sector && carrier.holder !== recipient)) {
454	              fail(message, "a sighting of no other carrier");
455	            }
456	            // Carriers last: a sighting only when no source or cache of the type exists at all.
457	            if (facts.sourceIslands.some((source) => source.type === sighting.type) || facts.cacheSectors.some((cache) => cache.type === sighting.type)) {
458	              fail(message, "a carrier sighting while a source or cache existed");
459	            }
460	          }
461	          if (tick < config.carrierRevealTick) {
462	            const snapshot = `${recipient}@${Math.floor((tick - config.controlStartTick) / interval)}`;
463	            const count = (this.sightings.get(snapshot) ?? 0) + 1;
464	            if (count > 1) fail(message, "a second sighting message in one snapshot");
465	            this.sightings.set(snapshot, count);
466	          }
467	          break;
468	        }
469	        case "no-lead":
470	          if (held.includes(body.type)) fail(message, "a no-lead for a held type");
471	          break;
472	      }
473	    }
474	    this.checkCharges(tick, facts, messages, state, requests, outcomes);
475	    this.checkPending(tick, facts, messages, state);
476	    this.checkFreeTriggers(tick, facts, messages, state, cappedBefore);
477	    this.previousState = state;
478	  }
479	
480	  /**
481	   * Every free trigger of this step (a type lost, or a journal rumor gone stale) whose type needs a carrier sighting
482	   * is in this step's sighting message or in the pending set, never in neither; and it waits only when the player's
483	   * sighting was already spent in this snapshot or the previous snapshot shows no other carrier of it. The pending set
484	   * then goes out at the next boundary (`checkPending`).
485	   */
486	  private checkFreeTriggers(tick: number, facts: Facts, messages: readonly IntelMessage[], state: IntelState, cappedBefore: ReadonlySet<string>): void {
487	    const previous = this.previousState;
488	    if (previous === undefined || !previous.started) return;
489	    const older = state.snapshots.length === 2 ? state.snapshots[0]! : undefined;
490	    const olderCarriers = older === undefined ? [] : this.carriersAt.get(older.tick)!;
491	    for (const now of state.players) {
492	      const before = previous.players.find((player) => player.id === now.id);
493	      if (before === undefined) continue;
494	      const held = facts.held.get(now.id)!;
495	      const mine = messages.filter((message) => message.to.kind === "player" && message.to.playerId === now.id).map((message) => message.body);
496	      const triggered = new Set([
497	        ...before.held.filter((type) => !held.includes(type)),
498	        ...mine.flatMap((body) => (body.kind === "rumor-stale" ? [body.type] : [])),
499	      ]);
500	      const sighted = new Set(mine.flatMap((body) => (body.kind === "carrier-sighting" ? body.sightings.map((sighting) => sighting.type) : [])));
501	      for (const type of triggered) {
502	        const needsSighting =
503	          !held.includes(type) &&
504	          !facts.sourceIslands.some((source) => source.type === type) &&
505	          !facts.cacheSectors.some((cache) => cache.type === type) &&
506	          facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== now.id);
507	        if (!needsSighting || sighted.has(type)) continue;
508	        if (!(now.pending?.types.some((pending) => pending.type === type) ?? false)) throw new Error(`tick ${tick}: ${now.id}'s free ${type} trigger was neither sighted nor queued`);
509	        const readable = olderCarriers.some((carrier) => carrier.type === type && carrier.holder !== now.id);
510	        if (readable && !cappedBefore.has(now.id)) throw new Error(`tick ${tick}: ${now.id}'s free ${type} trigger waits although the sighting was not spent`);
511	        EXERCISED.add("sighting:free-deferred");
512	      }
513	      if (sighted.size > 0 && [...triggered].some((type) => sighted.has(type))) EXERCISED.add("sighting:free-same-step");
514	    }
515	  }
516	
517	  /**
518	   * Charging (§11): per (player, type), at most one request is charged (`rumor` or `sighting`), and only when the one
519	   * lead of that type this step sends that player is a lead of that kind with the reason `targeted`: every lead per
520	   * (player, type) is kept, so a second, charged lead for a type a free lead covers fails. A request is `covered` only
521	   * when this step sends that player a lead of that type, or by free coverage, which the checker derives from the view:
522	   * the type's only eligible target is another player's carried copy, and either the minute-28 reveal has happened (the
523	   * broadcast gives it) or, with no boundary crossed in this step, the type was pending before it (the next boundary
524	   * gives it). A request under free coverage is always `covered`, never charged.
525	   */
526	  private checkCharges(
527	    tick: number,
528	    facts: Facts,
529	    messages: readonly IntelMessage[],
530	    state: IntelState,
531	    requests: readonly TargetedRumorRequest[],
532	    outcomes: readonly TargetedRumorOutcome[],
533	  ): void {
534	    const leads = new Map<string, string[]>();
535	    for (const message of messages) {
536	      if (message.to.kind !== "player") continue;
537	      const body = message.body;
538	      const found = body.kind === "rumor" ? [{ type: body.type, reason: body.reason, kind: "rumor" }] : body.kind === "carrier-sighting" ? body.sightings.map((sighting) => ({ ...sighting, kind: "sighting" })) : [];
539	      for (const { type, reason, kind } of found) {
540	        const key = `${message.to.playerId}/${type}`;
541	        leads.set(key, [...(leads.get(key) ?? []), `${kind}:${reason}`]);
542	      }
543	    }
544	    const previous = this.previousState;
545	    const crossed = (state.snapshots.at(-1)?.boundary ?? -1) > (previous?.snapshots.at(-1)?.boundary ?? -1);
546	    const freeCoverage = (playerId: string, type: RubbingType): "broadcast" | "pending" | null => {
547	      if (tick < this.config.controlStartTick || !facts.players.has(playerId)) return null;
548	      const carrierOnly =
549	        !facts.held.get(playerId)!.includes(type) &&
550	        !facts.sourceIslands.some((source) => source.type === type) &&
551	        !facts.cacheSectors.some((cache) => cache.type === type) &&
552	        facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== playerId);
553	      if (!carrierOnly) return null;
554	      if (tick >= this.config.carrierRevealTick) return "broadcast";
555	      const before = previous?.players.find((player) => player.id === playerId);
556	      return !crossed && (before?.pending?.types.some((pending) => pending.type === type) ?? false) ? "pending" : null;
557	    };
558	    const charged = new Map<string, number>();
559	    requests.forEach((request, index) => {
560	      const result = outcomes[index]!.result;
561	      if (result === "duplicate") return;
562	      const key = `${request.playerId}/${request.type}`;
563	      const sent = leads.get(key) ?? [];
564	      const coverage = freeCoverage(request.playerId, request.type);
565	      const fail = (why: string): never => {
566	        throw new Error(`tick ${tick}: request ${request.requestId} (${key}) ${result}: ${why}`);
567	      };
568	      if (coverage !== null && result !== "covered") fail(`answered although free coverage (${coverage}) holds`);
569	      if (result === "rumor" || result === "sighting") {
570	        charged.set(key, (charged.get(key) ?? 0) + 1);
571	        if (charged.get(key)! > 1) fail("charged twice for one (player, type)");
572	        if (sent.length !== 1 || sent[0] !== `${result}:targeted`) fail(`charged although the leads sent are ${sent.join(", ") || "nothing"}`);
573	      } else if (result === "covered") {
574	        if (sent.length === 0 && coverage === null) fail("covered by nothing");
575	        if (sent.length === 0) EXERCISED.add(`covered:${coverage}`);
576	      }
577	    });
578	  }
579	
580	  /** The islands of the player's journal rumors for the type that are still open. */
581	  private activeIslands(playerId: string, type: RubbingType): Set<number> {
582	    const islands = new Set<number>();
583	    for (const [key, rumor] of this.rumors) {
584	      if (!key.startsWith(`${playerId}#`) || rumor.closed || rumor.type !== type) continue;
585	      const target = rumor.target as { kind: string; island?: number };
586	      if (target.kind === "island") islands.add(target.island!);
587	    }
588	    return islands;
589	  }
590	
591	  /**
592	   * After every step, each player has at most one pending sighting message holding a set of types. At the first
593	   * boundary after a type was deferred, it goes out in a sighting, unless the checker finds it ineligible (held, a
594	   * source or cache exists, or no one else carries it), or finds no other carrier of it in the previous snapshot to
595	   * read, in which case it must still be pending.
596	   */
597	  private checkPending(tick: number, facts: Facts, messages: readonly IntelMessage[], state: IntelState): void {
598	    const fail = (why: string): never => {
599	      throw new Error(`tick ${tick}: ${why}`);
600	    };
601	    for (const player of state.players) {
602	      if (player.pending === null) continue;
603	      const types = player.pending.types.map((pending) => pending.type);
604	      if (types.length === 0) fail(`${player.id} has an empty pending message`);
605	      if (new Set(types).size !== types.length) fail(`${player.id} has a type pending twice`);
606	    }
607	    const previous = this.previousState;
608	    const newest = state.snapshots.at(-1);
609	    if (previous === undefined || newest === undefined || newest.boundary <= (previous.snapshots.at(-1)?.boundary ?? -1)) return;
610	    const older = state.snapshots.length === 2 ? state.snapshots[0]! : undefined;
611	    const olderCarriers = older === undefined ? [] : this.carriersAt.get(older.tick)!;
612	    for (const before of previous.players) {
613	      const now = state.players.find((player) => player.id === before.id);
614	      if (before.pending === null || now === undefined) continue;
615	      const sighted = new Set(
616	        messages.flatMap((message) =>
617	          message.to.kind === "player" && message.to.playerId === before.id && message.body.kind === "carrier-sighting"
618	            ? message.body.sightings.map((sighting) => sighting.type)
619	            : [],
620	        ),
621	      );
622	      for (const { type } of before.pending.types) {
623	        const stillPending = now.pending?.types.some((pending) => pending.type === type) ?? false;
624	        const eligible =
625	          !facts.held.get(before.id)!.includes(type) &&
626	          !facts.sourceIslands.some((source) => source.type === type) &&
627	          !facts.cacheSectors.some((cache) => cache.type === type) &&
628	          facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== before.id);
629	        const readable = olderCarriers.some((carrier) => carrier.type === type && carrier.holder !== before.id);
630	        if (sighted.has(type)) EXERCISED.add("sighting:deferred-delivered");
631	        else if (eligible && readable) fail(`${before.id}'s deferred ${type} sighting was not delivered at the boundary`);
632	        else if (eligible && !stillPending) fail(`${before.id}'s deferred ${type} sighting was dropped while eligible`);
633	        else if (!eligible && stillPending) fail(`${before.id}'s deferred ${type} sighting is still pending although ineligible`);
634	      }
635	    }
636	  }
637	}
638	
639	/** A seeded shuffle, leaving the input as it is. */
640	function shuffled<T>(items: readonly T[], draw: Draw): T[] {
641	  const out = [...items];
642	  for (let index = out.length - 1; index > 0; index--) {
643	    const other = draw(index + 1);
644	    [out[index], out[other]] = [out[other]!, out[index]!];
645	  }
646	  return out;
647	}
648	
649	/**
650	 * Adds purchases to a script so steps often carry several: one player buying one type twice, two players buying one
651	 * type, and purchases on the same tick as losses and replacements. Ids stay unique within a step.
652	 */
653	function withPurchases(script: readonly IntelReplayTick[], config: IntelConfig, seed: number): IntelReplayTick[] {
654	  const draw = generator(seed ^ 0x5eed);
655	  let next = 0;
656	  return script.map(({ view, requests }) => {
657	    const extra: TargetedRumorRequest[] = [];
658	    if (view.tick >= config.controlStartTick && view.players.length > 0 && draw(1000) < 120) {
659	      const count = 2 + draw(4);
660	      for (let index = 0; index < count; index++) {
661	        const repeat = extra.length > 0 && draw(3) === 0 ? extra[draw(extra.length)]! : undefined;
662	        const playerId = repeat !== undefined && draw(2) === 0 ? repeat.playerId : view.players[draw(view.players.length)]!.id;
663	        const type = repeat?.type ?? config.types[draw(config.types.length)]!;
664	        extra.push({ requestId: `buy-${next++}`, playerId, type });
665	      }
666	    }
667	    return deepFreeze({ view, requests: [...(requests ?? []), ...extra] });
668	  });
669	}
670	
671	function setup(scenario: Scenario) {
672	  const map = scenario.preset === "slice" ? SLICE_MAP : ALPHA_MAP;
673	  const config = createIntelConfig({
674	    preset: scenario.preset,
675	    finalIsland: { x: (map.widthTiles * T) >> 1, y: ((map.heightTiles * T) >> 1) + 77 },
676	    controlStartTick: START,
677	    map,
678	    ...(scenario.realTimes ? {} : { rules: QUICK_RULES }),
679	  });
680	  return { config, script: randomScript(scenario, config, map) };
681	}
682	
683	describe("intel property runs (§3, §5, §11, §16)", () => {
684	  for (const scenario of SCENARIOS) {
685	    it(`keep every message within the rules: ${scenario.name}`, { timeout: 120_000 }, () => {
686	      const { config, script } = setup(scenario);
687	      if (scenario.realTimes && scenario.skipPerMille === 0) {
688	        expect(config.carrierIntervalTicks).toBe(600);
689	        expect(script.at(-1)!.view.tick - config.controlStartTick).toBeGreaterThanOrEqual(36_000);
690	        expect(script.at(-1)!.view.tick).toBeGreaterThan(config.carrierRevealTick + 4 * config.carrierIntervalTicks);
691	      }
692	      const checker = new Checker(config, scenario.skipPerMille > 0);
693	      let state = createIntelState(config, scenario.seed);
694	      const kinds = new Set<string>();
695	      const messages: IntelMessage[] = [];
696	      for (const { view, requests } of script) {
697	        // Frozen (views are frozen too), so a step that wrote into its input would throw.
698	        const stepped = stepIntel(config, deepFreeze(state), view, requests ?? []);
699	        messages.push(...stepped.messages);
700	        expect(stepped.outcomes.map((outcome) => outcome.requestId)).toEqual((requests ?? []).map((request) => request.requestId));
701	        for (const outcome of stepped.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
702	        checker.check(view, stepped.messages, stepped.state, requests ?? [], stepped.outcomes);
703	        for (const message of stepped.messages) kinds.add(message.body.kind);
704	        state = stepped.state;
705	      }
706	      // The run reached the reveals it spans.
707	      expect(kinds.has("sector-reveal") && kinds.has("carrier-report")).toBe(true);
708	      // Replaying the same script from the same seed reaches the same state.
709	      const replayed = replayIntel(config, createIntelState(config, scenario.seed), script);
710	      expect(replayed.hash).toBe(hashState(state));
711	      expect(replayed.messages).toEqual(messages);
712	    });
713	  }
714	
715	  it("use compressed configs that the content validator accepts", () => {
716	    expect(validateIntelRules(QUICK_RULES)).toEqual({ ok: true, value: QUICK_RULES });
717	    expect(QUICK_RULES.carrierRevealTicks % QUICK_RULES.carrierIntervalTicks).toBe(0);
718	  });
719	
720	  for (const scenario of SCENARIOS.filter((candidate) => !candidate.realTimes)) {
721	    it(`give the same messages, outcomes and state for any order of a step's requests and view arrays: ${scenario.name}`, { timeout: 120_000 }, () => {
722	      const { config, script: plain } = setup(scenario);
723	      const script = withPurchases(plain, config, scenario.seed);
724	      const draw = generator(scenario.seed ^ 0xa11ce);
725	      const checker = new Checker(config, scenario.skipPerMille > 0);
726	      const byRequestId = (outcomes: readonly TargetedRumorOutcome[]) => [...outcomes].sort((a, b) => (a.requestId < b.requestId ? -1 : a.requestId > b.requestId ? 1 : 0));
727	      let listed = createIntelState(config, scenario.seed);
728	      let permuted = listed;
729	      let several = 0;
730	      for (const { view, requests } of script) {
731	        const asked = requests ?? [];
732	        const shuffledView: IntelWorldView = { tick: view.tick, players: shuffled(view.players, draw), rubbings: shuffled(view.rubbings, draw) };
733	        const a = stepIntel(config, listed, view, asked);
734	        const b = stepIntel(config, permuted, shuffledView, shuffled(asked, draw));
735	        expect(b.messages).toEqual(a.messages);
736	        expect(byRequestId(b.outcomes)).toEqual(byRequestId(a.outcomes));
737	        // The state hash on every step that asked or said something (hashing every quiet step too is slow), and at the end.
738	        if (asked.length > 0 || a.messages.length > 0) expect(hashState(b.state)).toBe(hashState(a.state));
739	        checker.check(view, a.messages, a.state, asked, a.outcomes);
740	        for (const outcome of a.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
741	        if (asked.length > 1) several++;
742	        listed = a.state;
743	        permuted = b.state;
744	      }
745	      expect(hashState(permuted)).toBe(hashState(listed));
746	      expect(several).toBeGreaterThan(20);
747	    });
748	  }
749	
750	  it("exercise every message kind, outcome and lead path (EXERCISED)", () => {
751	    expect(MUST_EXERCISE.filter((path) => !EXERCISED.has(path))).toEqual([]);
752	  });
753	});
